const modal=document.createElement('div');modal.className='phone-modal';modal.hidden=true;modal.innerHTML=`<section class="phone-dialog" role="dialog" aria-modal="true" aria-labelledby="phone-title"><header class="phone-header"><h2 id="phone-title">手机拍摄预览</h2><button id="close-phone" aria-label="关闭拍摄预览">×</button></header><div class="phone-body"><div class="phone-intro"><div><strong id="phone-location"></strong><p>预览舞台和人物在手机照片里有多大。</p></div><span class="badge">3D 取景示意</span></div><div class="phone-grid"><div class="phone-mat"><div id="phone-frame" class="phone-frame"><div class="phone-gridlines"></div><span class="phone-badge left" id="phone-zoom-tag"></span><span class="phone-badge right" id="phone-ratio-tag">4:3</span><span class="phone-watermark">估算场景 · 非实拍</span></div><p>拖动微调取景方向 · 切换倍数保持机位与朝向</p><div class="phone-presets">${[1,2,5,8,10].map(n=>`<button data-phone-zoom="${n}">${n}×</button>`).join('')}</div></div><div class="phone-settings"><div class="field"><label for="photo-section">拍摄分区</label><select id="photo-section"></select></div><div><label for="photo-depth">分区前后位置 · <span id="photo-depth-value"></span></label><input id="photo-depth" type="range" min="1" max="30" value="18"><div class="zoom-label"><span>靠前</span><span>靠后</span></div></div><div class="phone-pair"><button id="portrait">竖拍 3:4</button><button id="landscape" class="active">横拍 4:3</button></div><div class="phone-pair"><button id="aim-actor" class="active">◎ 对准示意人物</button><button id="aim-stage">对准舞台中央</button></div><button id="reset-phone" class="wide">↺ 重置取景方向</button><div class="phone-lens"><label for="photo-focal">通用手机估算 · 1× </label><input id="photo-focal" type="number" min="12" max="50" value="24"> mm</div><button id="export-phone" class="wide download">↓ 导出取景图</button><div id="phone-feedback" class="phone-feedback"></div><div class="phone-disclaimer">人物按 1.75 米示意；排座与距离为估算。用于比较构图与人物大小，不预测真实照片清晰度、灯光或人群遮挡。</div></div></div></div></section>`;document.body.append(modal);
